"""ORD_LINE renumbering migrated from Meridian CRM 4.2."""

from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Apply legacy numeric coercion: an empty value is numeric zero."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted lines and assign contiguous line numbers per order."""
    surviving: list[tuple[str, Decimal, int, dict]] = []

    for input_index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        ord_id = row.get("ORD_ID", "")
        line_no = row.get("LINE_NO", "")
        surviving.append(
            (str(ord_id), _numeric_line_no(line_no), input_index, row)
        )

    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_ord_id: str | None = None
    next_line_no = 0

    for ord_id, _, _, row in surviving:
        if ord_id != current_ord_id:
            current_ord_id = ord_id
            next_line_no = 1
        else:
            next_line_no += 1

        renumbered_row = dict(row)
        renumbered_row["LINE_NO"] = next_line_no
        result.append(renumbered_row)

    return result
